import time

class APIHandler:
    """REST API endpoint handler with rate limiting and validation."""

    def __init__(self):
        self.app = Flask(__name__)
        self.rate_limits = {}  # IP -> last request time
        self.setup_routes()

    def setup_routes(self):
        """Configure API endpoints."""
        @self.app.route('/api/data', methods=['POST'])
        def handle_data():
            return self._process_data_request(request)

        @self.app.route('/api/status', methods=['GET'])
        def handle_status():
            return self._process_status_request(request)

    def _check_rate_limit(self, ip_address, limit_seconds=1):
        """Check and enforce rate limiting."""
        current_time = time.time()
        if ip_address in self.rate_limits:
            if current_time - self.rate_limits[ip_address] < limit_seconds:
                return False
        self.rate_limits[ip_address] = current_time
        return True

    def _process_data_request(self, request):
