### 2. Caching Mechanisms (In-Memory & Redis Patterns)

```python
import redis
import pickle
import time
from functools import wraps

class CacheManager:
    """Unified caching interface supporting multiple backends."""

    def __init__(self, redis_host='localhost', redis_port=6379, default_ttl=3600):
        self.memory_cache = {}
        self.redis_client = None
        self.default_ttl = default_ttl

        try:
            self.redis_client = redis.Redis(host=redis_host, port=redis_port, db=0)
            self.redis_client.ping()  # Test connection
        except redis.ConnectionError:
            print("Redis not available, using in-memory cache only")

    def get(self, key):
        """Retrieve value from cache."""
        # Try Redis first
        if self.redis_client:
            try:
                cached = self.redis_client.get(key)
                if cached:
                    return pickle.loads(cached)
            except redis.RedisError:
                pass

        # Fall back to memory cache
        if key in self.memory_cache:
            entry = self.memory_cache[key]
            if time.time() < entry['expires']:
                return entry['value']
            else:
                del self.memory_cache[key]

        return None

    def set(self, key, value, ttl=None):
        """Store value in cache with TTL."""
        actual_ttl = ttl or self.default_ttl
        expires = time.time() + actual_ttl

        # Try Redis first
        if self.redis_client:
            try:
                serialized = pickle.dumps(value)
                self.redis_client.setex(key, actual_ttl, serialized)
                return True
            except redis.RedisError:
                pass

        # Fall back to memory cache
        self.memory_cache[key] = {
            'value': value,
            'expires': expires
        }
        return True

    def cache_result(self, ttl=None):
        """Decorator for caching function results."""
        def decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                cache_key = f"{func.__name__}:{str(args)}:{str(kwargs)}"
                cached = self.get(cache_key)
                if cached is not None:
                    return cached

                result = func(*args, **kwargs)
                self.set(cache_key, result, ttl)
                return result
            return wrapper
        return decorator

