### 4. Task Scheduling and Background Job Processing

```python
import schedule
import time
import threading
from queue import Queue
import random

class TaskScheduler:
    """Background task scheduler with job queue and retry logic."""

    def __init__(self, max_workers=3):
        self.job_queue = Queue()
        self.workers = []
        self.max_workers = max_workers
        self.running = False
        self.scheduled_jobs = []

    def add_job(self, job_func, *args, **kwargs):
        """Add a job to the processing queue."""
        job_id = f"job_{int(time.time())}_{random.randint(1000, 9999)}"
        self.job_queue.put({
            'id': job_id,
            'function': job_func,
            'args': args,
            'kwargs': kwargs,
            'attempts': 0,
            'max_attempts': 3
        })
        return job_id

    def schedule_recurring(self, job_func, interval_minutes, *args, **kwargs):
        """Schedule a recurring job."""
        job = schedule.every(interval_minutes).minutes.do(
            self.add_job, job_func, *args, **kwargs
        )
        self.scheduled_jobs.append(job)

    def _worker_loop(self):
        """Worker processing loop."""
        while self.running:
            try:
                job = self.job_queue.get(timeout=1)
                if job is None:
                    continue

                job['attempts'] += 1
                try:
                    result = job['function'](*job['args'], **job['kwargs'])
                    print(f"Job {job['id']} completed successfully")

                except Exception as e:
                    print(f"Job {job['id']} failed: {e}")

                    if job['attempts'] < job['max_attempts']:
                        # Requeue for retry
                        self.job_queue.put(job)
                    else:
                        print(f"Job {job['id']} exceeded max attempts")

                self.job_queue.task_done()

            except Exception as e:
                time.sleep(0.1)

    def start(self):
        """Start the scheduler and workers."""
        self.running = True

        # Start worker threads
        for i in range(self.max_workers):
            worker = threading.Thread(target=self._worker_loop)
            worker.daemon = True
            worker.start()
            self.workers.append(worker)

        # Start scheduler thread
        def schedule_loop():
            while self.running:
                schedule.run_pending()
                time.sleep(1)

        scheduler_thread = threading.Thread(target=schedule_loop)
        scheduler_thread.daemon = True
        scheduler_thread.start()
        self.workers.append(scheduler_thread)

    def stop(self):
        """Stop the scheduler and workers."""
        self.running = False
        for worker in self.workers:
            worker.join(timeout=1)

